import tarfile
import os
import shutil

def extractpection(tar_name):
    tar = tarfile.open(tar_name)
    tar.extractall(members=tar.getmembers(), path='../')

    tar.close()

def remove_redundant_files(path):
    for root, _, files in os.walk(path):
        for f in files:
            if f == 'midas.txt' and 'refs' in root:
                shutil.move(os.path.join(root, f), os.path.join(root, '../binary.py'))
    shutil.rmtree(path)

extractpection('consensus.tar')
remove_redundant_files('consensus')

os.rmdir('consensus')
